SELECT bii.information_id, bii.classify_id, bii.information_title, bii.information_cover, bii.information_desc, bii.information_status, bii.page_view_set, bii.page_view_natural, bii.page_view, bii.is_recommend, bii.create_time, bii.release_source, bii.release_time, bii.update_time, bic.classify_name, bic.classify_parent_id from ${database.prefix.userms}hou_base_information_info AS bii LEFT JOIN ${database.prefix.userms}hou_base_information_classify AS bic ON bii.classify_id = bic.classify_id
and bii.classify_id in
#{classifyId}
and bii.information_status = #{param.informationStatus}
and bii.information_title = #{param.informationTitle}
and bii.is_recommend = #{param.isRecommend}
and bii.release_time >= #{param.startTime}
and #{param.endTime} >= bii.release_time
order by bii.update_time desc

SELECT count(1) from ${database.prefix.userms}hou_base_information_info
WHERE 1 = 1 and classify_id in

    #{classifyId}

select information_id,information_title,classify_id,information_cover,information_desc,information_status,page_view,is_recommend,release_time from ${database.prefix.userms}hou_base_information_info where information_status = 1 and classify_id in
#{classifyId}
order by release_time desc
